#include "StdAfx.h"#include "KeybCOM.h"#include ".\PipeSerS.h"//CPipeSerS::CPipeSerS( const char* pszName, DWORD dwOut, DWORD dwInp ): m_hPipe(INVALID_HANDLE_VALUE), m_bRun(true), m_dwOut(dwOut), m_dwInp(dwInp)  {  memset( &ovl, 0, sizeof(ovl) );  lstrcpy( m_Name, pszName );  }CPipeSerS::~CPipeSerS(void)  {  Close();  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~bool CPipeSerS::MyErrExit(const char* text)  {  return 0;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~DWORD PIPE_TIMEOUT = 100;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~bool CPipeSerS::Open()  {  if ( ovl.hEvent == NULL )    ovl.hEvent = ::CreateEvent( NULL, TRUE, TRUE, NULL );  //  if ( ovl.hEvent == NULL )     MyErrExit("CreateEvent");  //  char name[256];  wsprintf( name, "\\\\.\\pipe\\%s",m_Name);  //  SECURITY_DESCRIPTOR* psd = (SECURITY_DESCRIPTOR*) LocalAlloc(LPTR, SECURITY_DESCRIPTOR_MIN_LENGTH);  InitializeSecurityDescriptor(psd, SECURITY_DESCRIPTOR_REVISION);  SetSecurityDescriptorDacl(psd, TRUE, NULL, FALSE);  //  SECURITY_ATTRIBUTES sa;  sa.nLength = sizeof(sa);  sa.lpSecurityDescriptor = psd;  sa.bInheritHandle = TRUE;  //  m_hPipe = ::CreateNamedPipe(          name,                    // pipe name          PIPE_ACCESS_DUPLEX |     // read/write access          FILE_FLAG_OVERLAPPED,    // overlapped mode          PIPE_TYPE_MESSAGE |      // message-type pipe          PIPE_READMODE_MESSAGE |  // message-read mode          PIPE_WAIT,               // blocking mode          10,                      // number of instances          m_dwOut,                 // output buffer size          m_dwInp,                 // input buffer size          PIPE_TIMEOUT,            // client time-out          &sa);                    // no security attributes   if ( m_hPipe == INVALID_HANDLE_VALUE )    return MyErrExit("CreatePipe");   //  return Connect();  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void CPipeSerS::Close()  {  m_bRun = false;  if ( ovl.hEvent != NULL )    {    //::CloseHandle( ovl.hEvent );    }  //  if ( m_hPipe != INVALID_HANDLE_VALUE )    {    ::CloseHandle(m_hPipe);    m_hPipe = INVALID_HANDLE_VALUE;    }  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~bool CPipeSerS::Connect()  {  BOOL fPendingIO = FALSE;   //  BOOL fConnected = ConnectNamedPipe( m_hPipe, &ovl);   if (fConnected)     return MyErrExit("ConnectNamedPipe");    switch (GetLastError())     {     // The overlapped connection in progress.     case ERROR_IO_PENDING:       fPendingIO = TRUE;     break;     // Client is already connected, so signal an event.     case ERROR_PIPE_CONNECTED:       if (SetEvent(ovl.hEvent))         break;     // If an error occurs during the connect operation...     default:       return MyErrExit("ConnectNamedPipe");    }   return fPendingIO == TRUE;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~bool CPipeSerS::Reconnect()  {  if ( !::DisconnectNamedPipe( m_hPipe ) )     return MyErrExit("DisconnectNamedPipe");   return Connect();  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void CPipeSerS::Run()  {  while ( m_bRun )    {    DWORD dwWait = WaitForSingleObject( ovl.hEvent, INFINITE );    if ( WAIT_OBJECT_0 != dwWait )      continue;    switch ( Action() )      {      default:      case  0:        break;      case  1:        return;      case -1:        Reconnect();        break;      }    }  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~DWORD WINAPI PipeFunc( LPVOID lpParam )  {  CPipeSerS* pipe = (CPipeSerS*)lpParam;  pipe->Run();  return 0;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void CPipeSerS::StartPipe(CPipeSerS* pipe)  {  if ( !pipe->Open() )    return;  DWORD dwThreadId;  pipe->m_hTread = ::CreateThread( NULL, 0, PipeFunc, (LPVOID)pipe, 0, &dwThreadId);  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void CPipeSerS::StopPipe(CPipeSerS* pipe)  {  ::CloseHandle(pipe->m_hTread);  pipe->Close();  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~